// ComplianceDashboard.jsx
import React, { useState, useRef } from 'react';
import './Dashboard.css';
import CompanyLogo from "../../../src/assets/gm_edited.jpg"
import RequirementDetail from '../requirementdetail/RequirementDetail';


// ------------------------------------------------------------
// Data
// ------------------------------------------------------------
const REQUIREMENTS = [
  // 1. Administrative, licensing, permits, and fees
  { category: 'Admin & Licensing', citation: '16 TAC §3.1 & §8.51', description: 'P-5 Organization Report renewal', due: '2027-07-12', status: 'on schedule', assigned: 'Jacob Kiage' },
  { category: 'Admin & Licensing', citation: '16 TAC §3.70', description: 'T-4 Permit to Operate renewal', due: '2027-07-12', status: 'action window', assigned: 'Maria Chen' },
  { category: 'Admin & Licensing', citation: '16 TAC §8.201', description: 'Pipeline safety/regulatory program fees', due: '2027-04-01', status: 'on schedule', assigned: 'Sam Ortiz' },
  { category: 'Admin & Licensing', citation: '49 CFR §191.11 / 16 TAC §8.210', description: 'Gas Distribution Annual Report', due: '2026-03-15', status: 'past due', assigned: 'Jacob Kiage' },
  { category: 'Admin & Licensing', citation: '49 CFR §191.17 / 16 TAC §8.210', description: 'Gas Transmission & Gathering Annual Report', due: '2026-03-15', status: 'past due', assigned: 'Aisha Patel' },
  { category: 'Admin & Licensing', citation: '16 TAC §8.230', description: 'School piping testing enforcement', due: '2026-07-01', status: 'action window', assigned: 'Carlos Reyes' },
  // 2. Manual reviews, procedures, and OQ
  { category: 'Manuals & OQ', citation: '49 CFR §192.605(a)', description: 'O&M manual review', due: '2026-09-01', status: 'on schedule', assigned: 'Dana Kim' },
  { category: 'Manuals & OQ', citation: '49 CFR §192.605(c)', description: 'Abnormal response/procedure effectiveness', due: '2026-08-15', status: 'on schedule', assigned: 'Evan Park' },
  { category: 'Manuals & OQ', citation: '49 CFR §192.615(b)', description: 'Emergency plan review & training', due: '2026-10-10', status: 'on schedule', assigned: 'Fiona Okafor' },
  { category: 'Manuals & OQ', citation: '49 CFR §192.631(x)', description: 'Control Room Management program review', due: '2026-12-01', status: 'on schedule', assigned: 'George Hill' },
  { category: 'Manuals & OQ', citation: '16 TAC §8.206(d)', description: 'Risk-based leak survey program review', due: '2027-01-15', status: 'on schedule', assigned: 'Hannah Wu' },
  // 3. Corrosion control
  { category: 'Corrosion Control', citation: '49 CFR §192.465(a)', description: 'CP pipeline testing', due: '2026-11-01', status: 'on schedule', assigned: 'Isabel Torres' },
  { category: 'Corrosion Control', citation: '49 CFR §192.465(b)', description: 'Rectifier & CP device inspections', due: '2026-08-20', status: 'action window', assigned: 'James Lee' },
  { category: 'Corrosion Control', citation: '49 CFR §192.465(c)', description: 'Critical interference bonds/diodes', due: '2026-10-05', status: 'on schedule', assigned: 'Kara Singh' },
  // 4. Patrolling, leakage, odorization
  { category: 'Patrolling & Odorization', citation: '49 CFR §192.705', description: 'ROW patrolling (Class 1-2)', due: '2026-09-30', status: 'on schedule', assigned: 'Liam O\'Brien' },
  { category: 'Patrolling & Odorization', citation: '49 CFR §192.706', description: 'Transmission leakage surveys', due: '2026-12-15', status: 'on schedule', assigned: 'Maya Patel' },
  { category: 'Patrolling & Odorization', citation: '49 CFR §192.721', description: 'Distribution line patrolling', due: '2026-07-25', status: 'action window', assigned: 'Noah Chen' },
  // 5. Equipment, valve, facility
  { category: 'Equipment & Valves', citation: '49 CFR §192.739', description: 'Pressure limiting/regulating station inspections', due: '2026-08-01', status: 'on schedule', assigned: 'Olivia Wright' },
  { category: 'Equipment & Valves', citation: '49 CFR §192.743', description: 'Relief device capacity verification', due: '2026-09-12', status: 'on schedule', assigned: 'Pablo Garcia' },
  { category: 'Equipment & Valves', citation: '49 CFR §192.745', description: 'Transmission emergency valve inspections', due: '2026-10-20', status: 'on schedule', assigned: 'Quinn Harper' },
  // 6. Public awareness
  { category: 'Public Awareness', citation: '49 CFR §192.616 / API RP 1162', description: 'Public awareness messaging', due: '2026-11-30', status: 'on schedule', assigned: 'Rachel Adams' },
  { category: 'Public Awareness', citation: '49 CFR §192.616(c)', description: 'Public awareness program effectiveness review', due: '2027-02-01', status: 'on schedule', assigned: 'Samira Khan' },
  { category: 'Public Awareness', citation: '49 CFR §192.939', description: 'Gas transmission integrity reassessment', due: '2027-03-15', status: 'on schedule', assigned: 'Tyler Brooks' },
];

const CATEGORIES = [
  { key: 'Admin & Licensing', label: 'Admin & Licensing' },
  { key: 'Manuals & OQ', label: 'Manuals & OQ' },
  { key: 'Corrosion Control', label: 'Corrosion Control' },
  { key: 'Patrolling & Odorization', label: 'Patrolling & Odorization' },
  { key: 'Equipment & Valves', label: 'Equipment & Valves' },
  { key: 'Public Awareness', label: 'Public Awareness' },
];

// helpers
const getStatusColor = (status) => {
  if (status === 'past due') return '#A23E2A';
  if (status === 'action window') return '#C98A1E';
  return '#3F6B52';
};

// ------------------------------------------------------------
// Dial component (analog gauge)
// ------------------------------------------------------------
const Dial = ({ status, size = 28 }) => {
  const color = getStatusColor(status);
  let angle = -60;
  if (status === 'action window') angle = 0;
  if (status === 'past due') angle = 60;
  const strokeWidth = size * 0.12;
  const radius = size * 0.38;
  const center = size / 2;
  const startAngle = -120;
  const endAngle = 120;
  const sweep = endAngle - startAngle;
  const needleAngle = startAngle + (sweep * (angle + 60) / 120);
  const needleRad = (needleAngle * Math.PI) / 180;
  const needleLength = radius * 0.8;
  const needleX = center + needleLength * Math.cos(needleRad);
  const needleY = center + needleLength * Math.sin(needleRad);

  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="dial-svg">
      <circle cx={center} cy={center} r={radius} fill="none" stroke="#d0d9d4" strokeWidth={strokeWidth * 0.6} />
      <circle cx={center} cy={center} r={radius * 0.3} fill="none" stroke="#3D5560" strokeWidth={strokeWidth * 0.3} />
      <line x1={center} y1={center} x2={needleX} y2={needleY} stroke={color} strokeWidth={strokeWidth * 0.9} strokeLinecap="round" />
      <circle cx={center} cy={center} r={strokeWidth * 0.8} fill="#14191C" />
      <path d={`M ${center + radius * Math.cos(-120 * Math.PI / 180)} ${center + radius * Math.sin(-120 * Math.PI / 180)} A ${radius} ${radius} 0 0 1 ${center + radius * Math.cos(-60 * Math.PI / 180)} ${center + radius * Math.sin(-60 * Math.PI / 180)}`} fill="none" stroke="#3F6B52" strokeWidth={strokeWidth * 0.5} opacity="0.6" />
      <path d={`M ${center + radius * Math.cos(-20 * Math.PI / 180)} ${center + radius * Math.sin(-20 * Math.PI / 180)} A ${radius} ${radius} 0 0 1 ${center + radius * Math.cos(20 * Math.PI / 180)} ${center + radius * Math.sin(20 * Math.PI / 180)}`} fill="none" stroke="#C98A1E" strokeWidth={strokeWidth * 0.5} opacity="0.6" />
      <path d={`M ${center + radius * Math.cos(60 * Math.PI / 180)} ${center + radius * Math.sin(60 * Math.PI / 180)} A ${radius} ${radius} 0 0 1 ${center + radius * Math.cos(120 * Math.PI / 180)} ${center + radius * Math.sin(120 * Math.PI / 180)}`} fill="none" stroke="#A23E2A" strokeWidth={strokeWidth * 0.5} opacity="0.6" />
    </svg>
  );
};

// ------------------------------------------------------------
// Main Component
// ------------------------------------------------------------
const ComplianceDashboard = () => {
  const [activeCategory, setActiveCategory] = useState(null);
  const [selectedRequirement, setSelectedRequirement] = useState(null);
  const ledgerRef = useRef(null);

  // category worst status
  const categoryStatus = (catKey) => {
    const items = REQUIREMENTS.filter(r => r.category === catKey);
    if (items.some(r => r.status === 'past due')) return 'past due';
    if (items.some(r => r.status === 'action window')) return 'action window';
    return 'on schedule';
  };

  const scrollToCategory = (cat) => {
    setActiveCategory(cat);
    const el = document.getElementById(`cat-${cat.replace(/\s/g, '')}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  // opens the detail view for a given ledger row
  const handleRequirementClick = (req) => {
    setSelectedRequirement(req);
  };

  // returns to the ledger from the detail view
  const handleBackToLedger = () => {
    setSelectedRequirement(null);
  };

  // wire these up to real logic whenever you're ready
  const handleMarkComplete = () => {
    // e.g. call an API to mark selectedRequirement complete,
    // then setSelectedRequirement(null) to return to the ledger
  };

  const handleDispatchVendor = () => {
    // e.g. open a vendor dispatch modal/flow for selectedRequirement
  };

  return (
    <div className="app-container">
      {/* Sidebar - full height */}
      <aside className="sidebar">
        <div className="brand">
         <img
            src={CompanyLogo}
            alt="Galaxy Midstream"
            className="company-logo"
          />
        </div>

        <div className="operator-section">
          <div className="operator-label">OPERATOR</div>
          <div className="operator-name">Yunoya LTD</div>
        </div>

        <nav className="sidebar-nav">
          <a href="#" className="active">
            <i className="fas fa-tachometer-alt"></i>
            <span>INSTRUMENT PANEL</span>
          </a>
          <a href="#">
            <i className="fas fa-arrow-up"></i>
            <span>ESCALATION LADDER</span>
          </a>
          <a href="#">
            <i className="fas fa-store"></i>
            <span>VENDORS</span>
          </a>
          <a href="#">
            <i className="fas fa-chart-bar"></i>
            <span>REPORTS</span>
          </a>
          <a href="#">
            <i className="fas fa-archive"></i>
            <span>AUDIT ARCHIVE</span>
          </a>
          <a href="#">
            <i className="fas fa-cog"></i>
            <span>SYSTEM SETTINGS</span>
          </a>
          <a href="#">
            <i className="fas fa-user-shield"></i>
            <span>SYSTEM ADMIN</span>
          </a>
        </nav>

        <div className="user-badge">
          <strong>Jacob Kiage</strong>
          <span className="user-dot">●</span>
        </div>
      </aside>

      {/* Main content */}
      <main className="main-content">
        {selectedRequirement ? (
          // Detail view for the selected citation
          <RequirementDetail
            requirement={selectedRequirement}
            onBack={handleBackToLedger}
            onMarkComplete={handleMarkComplete}
            onDispatchVendor={handleDispatchVendor}
          />
        ) : (
          // Regular dashboard view
          <>
            {/* Route spine with inverted L junction */}
            <div className="route-spine-wrapper">
              <div className="route-spine">
                {CATEGORIES.map((cat, idx) => (
                  <React.Fragment key={cat.key}>
                    <button className="spine-node" onClick={() => scrollToCategory(cat.key)}>
                      <Dial status={categoryStatus(cat.key)} size={28} />
                      <span className="node-label">{cat.label}</span>
                    </button>
                    {idx < CATEGORIES.length - 1 && <span className="spine-connector"></span>}
                  </React.Fragment>
                ))}
              </div>
              {/* This empty div creates the inverted L junction */}
              <div className="spine-end-cap"></div>
            </div>

            {/* Ledger + Escalation - side by side */}
            <div className="dashboard-grid">
              <div className="ledger-scroll" ref={ledgerRef}>
                <table>
                  <thead>
                    <tr>
                      <th style={{ width: 32 }}> </th>
                      <th>Citation</th>
                      <th>Requirement</th>
                      <th>Due Date</th>
                      <th>Assigned To</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {CATEGORIES.map(cat => {
                      const items = REQUIREMENTS.filter(r => r.category === cat.key);
                      return (
                        <React.Fragment key={cat.key}>
                          <tr className="category-label" id={`cat-${cat.key.replace(/\s/g, '')}`}>
                            <td colSpan="6">
                              <span className="category-header">
                                <Dial status={categoryStatus(cat.key)} size={24} />
                                <strong>{cat.label}</strong>
                                <span className="all-ok">ALL OK</span>
                              </span>
                            </td>
                          </tr>
                          {items.map((req, idx) => (
                            <tr
                              key={idx}
                              className="clickable-row"
                              onClick={() => handleRequirementClick(req)}
                            >
                              <td className="td-dial"><Dial status={req.status} size={26} /></td>
                              <td className="td-citation">{req.citation}</td>
                              <td>{req.description}</td>
                              <td className="td-due">{req.due}</td>
                              <td className="td-assign">{req.assigned}</td>
                              <td className="td-status">
                                <span className="status-dot" style={{ background: getStatusColor(req.status) }}></span>
                                {req.status}
                              </td>
                            </tr>
                          ))}
                        </React.Fragment>
                      );
                    })}
                  </tbody>
                </table>
              </div>

              {/* Escalation ladder - side by side with ledger, top touches route spine */}
              <div className="escalation-rail">
                <h4>Escalation Ladder</h4>
                <div className="escalation-item highlight">
                  <span className="name">Jacob Kiage</span>
                  <span className="role">Compliance Lead</span>
                  <span className="badge">Overdue</span>
                </div>
                <div className="escalation-item">
                  <span className="name">Maria Chen</span>
                  <span className="role">Permits Specialist</span>
                </div>
                <div className="escalation-item">
                  <span className="name">Sam Ortiz</span>
                  <span className="role">Field Ops</span>
                </div>
                <div className="escalation-item">
                  <span className="name">Aisha Patel</span>
                  <span className="role">Reporting</span>
                </div>
                <div className="escalation-item">
                  <span className="name">Carlos Reyes</span>
                  <span className="role">Safety</span>
                </div>
                <div className="escalation-item" style={{ borderBottom: 'none' }}>
                  <span className="name">Dana Kim</span>
                  <span className="role">OQ Coordinator</span>
                </div>
              </div>
            </div>
          </>
        )}
      </main>
    </div>
  );
};

export default ComplianceDashboard;
